import { randomBytes } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync, chmodSync, chownSync, statSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Configs generated by this project are JSON, which is also valid YAML.
// Preserve all existing homeserver keys, accounts and other AS registrations.
export function initializeAgentService() {
  const root = resolve(process.env.MATRIX_HOMESERVER_STATE ?? 'state/matrix-homeserver');
  const state = resolve(process.env.AGENT_SERVICE_STATE ?? 'state/agent-service');
  const secrets = resolve(process.env.AGENT_SERVICE_SECRETS ?? 'state/agent-service-secrets');
  const synapse = resolve(process.env.MATRIX_SYNAPSE_DIR ?? join(root, 'synapse'));
  const configPath = join(synapse, 'homeserver.yaml');
  const config = JSON.parse(readFileSync(configPath, 'utf8'));
  if (!/^[a-zA-Z0-9.-]+(?::[0-9]+)?$/.test(config.server_name)) throw new Error('invalid_server_name');
  for (const directory of [state, secrets]) mkdirSync(directory, { recursive: true, mode: 0o700 });
  const secret = (name) => {
    const path = join(secrets, name);
    if (!existsSync(path)) writeFileSync(path, randomBytes(32).toString('base64url')+'\n', { mode: 0o600, flag: 'wx' });
    return readFileSync(path, 'utf8').trim();
  };
  const registration = {
    id: 'agent-router', url: process.env.AGENT_SERVICE_INTERNAL_URL ?? 'http://agent-service:8790',
    as_token: secret('as-token'), hs_token: secret('hs-token'), sender_localpart: '_ar_service',
    namespaces: { users: [{ exclusive: true, regex: '^@_ar_[a-f0-9]{32}:'+config.server_name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')+'$' }], aliases: [], rooms: [] },
    rate_limited: false, receive_ephemeral: false,
  };
  const registrationPath = join(synapse, 'agent-router-registration.yaml');
  if (existsSync(registrationPath)) {
    const prior = JSON.parse(readFileSync(registrationPath, 'utf8'));
    if (JSON.stringify(prior) !== JSON.stringify(registration)) throw new Error('existing_application_registration_differs: review configuration before changing it');
  } else writeFileSync(registrationPath, JSON.stringify(registration, null, 2)+'\n', { mode: 0o600, flag: 'wx' });
  const entry = '/data/agent-router-registration.yaml';
  config.app_service_config_files ??= [];
  if (!config.app_service_config_files.includes(entry)) {
    const backup = configPath+'.before-agent-service';
    if (!existsSync(backup)) writeFileSync(backup, readFileSync(configPath), { mode: 0o600, flag: 'wx' });
    config.app_service_config_files.push(entry);
    writeFileSync(configPath+'.new', JSON.stringify(config, null, 2)+'\n', { mode: 0o600 });
    if (process.getuid?.() === 0) {
      const prior = statSync(configPath); chownSync(configPath+'.new', prior.uid, prior.gid);
    }
    renameSync(configPath+'.new', configPath);
  }
  if (process.getuid?.() === 0) {
    const owner = statSync(configPath); chownSync(registrationPath, owner.uid, owner.gid);
    for (const path of [state, secrets, join(secrets, 'as-token'), join(secrets, 'hs-token')]) chownSync(path, 1000, 1000);
  }
  chmodSync(registrationPath, 0o600);
  process.stdout.write(JSON.stringify({ server: config.server_name, agentService: 'initialized', registration: entry })+'\n');
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) initializeAgentService();
